CREATE TABLE IF NOT EXISTS type3_studies (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, model_version INTEGER NOT NULL CHECK(model_version=2), version INTEGER NOT NULL CHECK(version>=0), state_json TEXT NOT NULL CHECK(json_valid(state_json)), state_digest TEXT NOT NULL CHECK(length(state_digest)=64), commit_token TEXT NOT NULL, CHECK(length(state_json)<=1000000));
CREATE TABLE IF NOT EXISTS type3_commands (study_id TEXT NOT NULL REFERENCES type3_studies(id), sequence INTEGER NOT NULL CHECK(sequence>0), request_id TEXT NOT NULL, command_json TEXT NOT NULL CHECK(json_valid(command_json)), state_digest TEXT NOT NULL CHECK(length(state_digest)=64), PRIMARY KEY(study_id,sequence), UNIQUE(study_id,request_id));
CREATE TABLE IF NOT EXISTS type3_maintenance (id TEXT PRIMARY KEY CHECK(id='recovery'), checked_at TEXT NOT NULL, studies INTEGER NOT NULL CHECK(studies>=0));
